begin;

-- مجموعة: ١٠ أسئلة (نفس عقد StoredQuestion)
insert into public.worship_quiz_bank (questions, model)
select '[{"question":"ما معنى كلمة ''الحمد'' في عبارة ''الحمد لله رب العالمين''؟","options":["ثناء وشكر لله","طلب من الله","دعوة للعبادة","إقرار بالخطأ"],"correct":0,"source":"سورة الفاتحة، الآية ٢","explanation":"الحمد تعني الثناء والشكر لله على نعمه."},{"question":"ما هو تعريف الإيمان حسب الحديث النبوي الشريف؟","options":["الإيمان أن يَحبَّ المرءُ ما يحبُّ اللهُ ويكره ما يكرهُ اللهُ","الإيمان هو الصلاة فقط","الإيمان هو الصوم فقط","الإيمان هو الجهاد"],"correct":0,"source":"صحيح البخاري، باب الإيمان، حديث 52","explanation":"الحديث يوضح أن الإيمان يشمل محبة ما يحب الله وكره ما يكرهه."},{"question":"ما هو الاسم الأعظم لله في الإسلام؟","options":["الرحمن","الرحيم","الله","الملك"],"correct":2,"source":"العقيدة الإسلامية المتفق عليها","explanation":"الاسم الأعظم هو ''الله'' وهو اسم الجلالة."},{"question":"في أي سنة هاجر النبي ﷺ من مكة إلى المدينة؟","options":["622 م","610 م","630 م","640 م"],"correct":0,"source":"سيرة النبي ﷺ، السنة الأولى للهجرة","explanation":"الهجرة وقعت في السنة الأولى للهجرة، أي 622 م."},{"question":"كم عدد ركعات صلاة الفجر؟","options":["ركعتان","أربع ركعات","ثلاث ركعات","خمس ركعات"],"correct":0,"source":"صحيح مسلم، باب صلاة الفجر، حديث 657","explanation":"صلاة الفجر فرضها الله ركعتين فقط."},{"question":"أي سورة تُعرف بـ ''قلب القرآن''؟","options":["سورة البقرة","سورة يس","سورة الإخلاص","سورة الملك"],"correct":1,"source":"صحيح البخاري، باب فضل سورة يس، حديث 4970","explanation":"سورة يس تُلقّب بـ ''قلب القرآن'' لما فيها من معانٍ مركّزة."},{"question":"ما هو الثواب لمن قال لا إله إلا الله؟","options":["يدخل الجنة","يحصل على مال كثير","يعفى من الصيام","يُعطى شرفًا في الدنيا"],"correct":0,"source":"صحيح البخاري، باب الإيمان، حديث 8","explanation":"الحديث يبين أن قول لا إله إلا الله يدخل صاحبه الجنة."},{"question":"أي مما يلي يُعَدُّ من أركان الإيمان الستة؟","options":["الإيمان بالملائكة","الإيمان بالمال","الإيمان بالزواج","الإيمان بالسلطة"],"correct":0,"source":"صحيح مسلم، باب أركان الإيمان، حديث 1","explanation":"الإيمان بالملائكة هو أحد أركان الإيمان الستة."},{"question":"ما اسم الغار الذي نزل فيه الوحي لأول مرة؟","options":["غار حراء","غار ثور","غار الفرات","غار مري"],"correct":0,"source":"سورة العلق، الآية 1، وتفاصيل السيرة النبوية","explanation":"النبي ﷺ نزل به الوحي في غار حراء."},{"question":"ما هي الأيام المفروضة على الصيام في شهر رمضان؟","options":["كل أيام الشهر","عشرة أيام فقط","كل الأيام ما عدا عيد الفطر","كل الأيام ما عدا اليوم الثالث عشر"],"correct":0,"source":"سورة البقرة، الآية 185","explanation":"الآية تأمر بالصيام في كل أيام شهر رمضان."}]'::jsonb, 'openai/gpt-oss-120b'
where not exists (
  select 1 from public.worship_quiz_bank
  where questions = '[{"question":"ما معنى كلمة ''الحمد'' في عبارة ''الحمد لله رب العالمين''؟","options":["ثناء وشكر لله","طلب من الله","دعوة للعبادة","إقرار بالخطأ"],"correct":0,"source":"سورة الفاتحة، الآية ٢","explanation":"الحمد تعني الثناء والشكر لله على نعمه."},{"question":"ما هو تعريف الإيمان حسب الحديث النبوي الشريف؟","options":["الإيمان أن يَحبَّ المرءُ ما يحبُّ اللهُ ويكره ما يكرهُ اللهُ","الإيمان هو الصلاة فقط","الإيمان هو الصوم فقط","الإيمان هو الجهاد"],"correct":0,"source":"صحيح البخاري، باب الإيمان، حديث 52","explanation":"الحديث يوضح أن الإيمان يشمل محبة ما يحب الله وكره ما يكرهه."},{"question":"ما هو الاسم الأعظم لله في الإسلام؟","options":["الرحمن","الرحيم","الله","الملك"],"correct":2,"source":"العقيدة الإسلامية المتفق عليها","explanation":"الاسم الأعظم هو ''الله'' وهو اسم الجلالة."},{"question":"في أي سنة هاجر النبي ﷺ من مكة إلى المدينة؟","options":["622 م","610 م","630 م","640 م"],"correct":0,"source":"سيرة النبي ﷺ، السنة الأولى للهجرة","explanation":"الهجرة وقعت في السنة الأولى للهجرة، أي 622 م."},{"question":"كم عدد ركعات صلاة الفجر؟","options":["ركعتان","أربع ركعات","ثلاث ركعات","خمس ركعات"],"correct":0,"source":"صحيح مسلم، باب صلاة الفجر، حديث 657","explanation":"صلاة الفجر فرضها الله ركعتين فقط."},{"question":"أي سورة تُعرف بـ ''قلب القرآن''؟","options":["سورة البقرة","سورة يس","سورة الإخلاص","سورة الملك"],"correct":1,"source":"صحيح البخاري، باب فضل سورة يس، حديث 4970","explanation":"سورة يس تُلقّب بـ ''قلب القرآن'' لما فيها من معانٍ مركّزة."},{"question":"ما هو الثواب لمن قال لا إله إلا الله؟","options":["يدخل الجنة","يحصل على مال كثير","يعفى من الصيام","يُعطى شرفًا في الدنيا"],"correct":0,"source":"صحيح البخاري، باب الإيمان، حديث 8","explanation":"الحديث يبين أن قول لا إله إلا الله يدخل صاحبه الجنة."},{"question":"أي مما يلي يُعَدُّ من أركان الإيمان الستة؟","options":["الإيمان بالملائكة","الإيمان بالمال","الإيمان بالزواج","الإيمان بالسلطة"],"correct":0,"source":"صحيح مسلم، باب أركان الإيمان، حديث 1","explanation":"الإيمان بالملائكة هو أحد أركان الإيمان الستة."},{"question":"ما اسم الغار الذي نزل فيه الوحي لأول مرة؟","options":["غار حراء","غار ثور","غار الفرات","غار مري"],"correct":0,"source":"سورة العلق، الآية 1، وتفاصيل السيرة النبوية","explanation":"النبي ﷺ نزل به الوحي في غار حراء."},{"question":"ما هي الأيام المفروضة على الصيام في شهر رمضان؟","options":["كل أيام الشهر","عشرة أيام فقط","كل الأيام ما عدا عيد الفطر","كل الأيام ما عدا اليوم الثالث عشر"],"correct":0,"source":"سورة البقرة، الآية 185","explanation":"الآية تأمر بالصيام في كل أيام شهر رمضان."}]'::jsonb
);

-- مجموعة: ١٠ أسئلة (نفس عقد StoredQuestion)
insert into public.worship_quiz_bank (questions, model)
select '[{"question":"في أي سورة ورد قوله تعالى: \"لا إكراه في الدين\"؟","options":["سورة البقرة","سورة الأنعام","سورة الحجرات","سورة المائدة"],"correct":0,"source":"سورة البقرة، الآية 256","explanation":"الآية 256 من سورة البقرة تنص على عدم الإكراه في الدين."},{"question":"أي من الأحاديث التالية يعرّف الإسلام كما رواه الصحابي جبارة بن مطعم؟","options":["صحيح البخاري، كتاب الإيمان، باب تعريف الإيمان","صحيح مسلم، كتاب الإيمان، باب الإيمان","مسند أحمد، باب الإيمان","سنن الترمذي، باب الإيمان"],"correct":0,"source":"صحيح البخاري، باب تعريف الإيمان","explanation":"الحديث يوضح أن الإسلام هو شهادة أن لا إله إلا الله وأن محمدًا رسول الله."},{"question":"أي من العبارات التالية يُعَدُّ من أركان الإيمان الستة؟","options":["الإيمان بالملائكة","الإيمان بالزكاة","الإيمان بالصيام","الإيمان بالحج"],"correct":0,"source":"العقيدة الإسلامية المتفق عليها","explanation":"الإيمان بالملائكة هو أحد أركان الإيمان الستة."},{"question":"في أي سنة هاجر النبي ﷺ من مكة إلى المدينة؟","options":["610 م","615 م","622 م","630 م"],"correct":2,"source":"السيرة النبوية، السنة الأولى للهجرة","explanation":"الهجرة وقعت في السنة الأولى للتقويم الهجري، أي 622 م."},{"question":"أي ركن من أركان الإسلام يُؤَدَّى خمس مرات يوميًا؟","options":["الزكاة","الشهادة","الصلاة","الحج"],"correct":2,"source":"القرآن الكريم، سورة البقرة، الآية 238","explanation":"الآية تحث على إقامة الصلاة، وهي خمس صلوات مفروضة يوميًا."},{"question":"أي سورة تُعرف بـ \"الفاتحة\" وتحتوي على سبع آيات؟","options":["سورة الفاتحة","سورة الإخلاص","سورة المسد","سورة الناس"],"correct":0,"source":"سورة الفاتحة، الآيات 1-7","explanation":"سورة الفاتحة هي السورة الافتتاحية في القرآن وتتألف من سبع آيات."},{"question":"أي حديث صحيح يبيّن أن الأعمال بالنيات؟","options":["صحيح البخاري، باب النية","صحيح مسلم، باب النية","صحيح ابن ماجه، باب النية","صحيح الترمذي، باب النية"],"correct":0,"source":"صحيح البخاري، باب النية","explanation":"هذا الحديث يوضح أن قيمة العمل تحدد بنيه."},{"question":"أي من أسماء الله الحسنى تعني \"الغني عن الحاجة\"؟","options":["القدير","الملك","الغني","الرحمن"],"correct":2,"source":"القرآن الكريم، سورة الحديد، الآية 7","explanation":"اسم \"الغني\" يدل على أن الله لا يحتاج إلى شيء."},{"question":"من كانت أول من أسلم من النساء؟","options":["خديجة بنت خويلد","عائشة بنت أبي بكر","فاطمة الزهراء","زينب بنت جحش"],"correct":0,"source":"السيرة النبوية","explanation":"خديجة بنت خويلد آمنت بالنبي ﷺ أولاً من النساء."},{"question":"في أي شهر يصوم المسلمون صوم رمضان؟","options":["شوال","ذو الحجة","رمضان","محرم"],"correct":2,"source":"القرآن الكريم، سورة البقرة، الآية 185","explanation":"الآية تأمر بصوم شهر رمضان."}]'::jsonb, 'openai/gpt-oss-120b'
where not exists (
  select 1 from public.worship_quiz_bank
  where questions = '[{"question":"في أي سورة ورد قوله تعالى: \"لا إكراه في الدين\"؟","options":["سورة البقرة","سورة الأنعام","سورة الحجرات","سورة المائدة"],"correct":0,"source":"سورة البقرة، الآية 256","explanation":"الآية 256 من سورة البقرة تنص على عدم الإكراه في الدين."},{"question":"أي من الأحاديث التالية يعرّف الإسلام كما رواه الصحابي جبارة بن مطعم؟","options":["صحيح البخاري، كتاب الإيمان، باب تعريف الإيمان","صحيح مسلم، كتاب الإيمان، باب الإيمان","مسند أحمد، باب الإيمان","سنن الترمذي، باب الإيمان"],"correct":0,"source":"صحيح البخاري، باب تعريف الإيمان","explanation":"الحديث يوضح أن الإسلام هو شهادة أن لا إله إلا الله وأن محمدًا رسول الله."},{"question":"أي من العبارات التالية يُعَدُّ من أركان الإيمان الستة؟","options":["الإيمان بالملائكة","الإيمان بالزكاة","الإيمان بالصيام","الإيمان بالحج"],"correct":0,"source":"العقيدة الإسلامية المتفق عليها","explanation":"الإيمان بالملائكة هو أحد أركان الإيمان الستة."},{"question":"في أي سنة هاجر النبي ﷺ من مكة إلى المدينة؟","options":["610 م","615 م","622 م","630 م"],"correct":2,"source":"السيرة النبوية، السنة الأولى للهجرة","explanation":"الهجرة وقعت في السنة الأولى للتقويم الهجري، أي 622 م."},{"question":"أي ركن من أركان الإسلام يُؤَدَّى خمس مرات يوميًا؟","options":["الزكاة","الشهادة","الصلاة","الحج"],"correct":2,"source":"القرآن الكريم، سورة البقرة، الآية 238","explanation":"الآية تحث على إقامة الصلاة، وهي خمس صلوات مفروضة يوميًا."},{"question":"أي سورة تُعرف بـ \"الفاتحة\" وتحتوي على سبع آيات؟","options":["سورة الفاتحة","سورة الإخلاص","سورة المسد","سورة الناس"],"correct":0,"source":"سورة الفاتحة، الآيات 1-7","explanation":"سورة الفاتحة هي السورة الافتتاحية في القرآن وتتألف من سبع آيات."},{"question":"أي حديث صحيح يبيّن أن الأعمال بالنيات؟","options":["صحيح البخاري، باب النية","صحيح مسلم، باب النية","صحيح ابن ماجه، باب النية","صحيح الترمذي، باب النية"],"correct":0,"source":"صحيح البخاري، باب النية","explanation":"هذا الحديث يوضح أن قيمة العمل تحدد بنيه."},{"question":"أي من أسماء الله الحسنى تعني \"الغني عن الحاجة\"؟","options":["القدير","الملك","الغني","الرحمن"],"correct":2,"source":"القرآن الكريم، سورة الحديد، الآية 7","explanation":"اسم \"الغني\" يدل على أن الله لا يحتاج إلى شيء."},{"question":"من كانت أول من أسلم من النساء؟","options":["خديجة بنت خويلد","عائشة بنت أبي بكر","فاطمة الزهراء","زينب بنت جحش"],"correct":0,"source":"السيرة النبوية","explanation":"خديجة بنت خويلد آمنت بالنبي ﷺ أولاً من النساء."},{"question":"في أي شهر يصوم المسلمون صوم رمضان؟","options":["شوال","ذو الحجة","رمضان","محرم"],"correct":2,"source":"القرآن الكريم، سورة البقرة، الآية 185","explanation":"الآية تأمر بصوم شهر رمضان."}]'::jsonb
