-- مجموعة: ١٠ أسئلة (نفس عقد StoredQuestion)
insert into public.worship_quiz_bank (questions, model)
select '[{"question":"ما هو الهدف الأساسي من خلق الإنسان حسب القرآن الكريم؟","options":["لعبادة الله","لتملك الأرض","للتمتع بالحياة الدنيوية","لإثبات التفوق البشري"],"correct":0,"source":"سورة الذاريات، الآية 56","explanation":"قال الله تعالى: {وما خلقت الجن والإنس إلا ليعبدون} وهو الهدف من الخلق."},{"question":"ما هو شرط صحة العمل في الإسلام بحسب الحديث النبوي؟","options":["النية الصادقة","الوقت المناسب","المكان المناسب","الملابس النظيفة"],"correct":0,"source":"صحيح البخاري، حديث 1","explanation":"قال النبي ﷺ: «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى»."},{"question":"أي من الأسماء التالية من أسماء الله الحسنى يدل على وحدانية الله؟","options":["الرحمن","القدوس","الغفور","الواسع"],"correct":1,"source":"سورة الحجر، الآية 23","explanation":"قال الله تعالى: {هو الله الواحد الصمد} ومن أسمائه «القدوس» تدل على تنزيه الله عن كل نقص."},{"question":"في أي سورة نزل أولى آيات الوحي على النبي محمد ﷺ؟","options":["سورة الفاتحة","سورة البقرة","سورة العلق","سورة الإخلاص"],"correct":2,"source":"سورة العلق، الآيات 1-5","explanation":"نزلت أولى كلمات الوحي في: «اقرأ باسم ربك الذي خلق…»"},{"question":"أي من الأركان التالية ليست من أركان الوضوء بحسب السنة النبوية؟","options":["غسل الوجه","غسل اليدين","غسل القدمين","غسل الأذنين"],"correct":3,"source":"صحيح مسلم، كتاب الوضوء، حديث 258","explanation":"الوضوء يتضمن غسل الوجه، اليدين، مسح الرأس، وغسل القدمين، ولا يشمل غسل الأذنين."},{"question":"من هو الأخ الذي باع يوسف عليه السلام إلى التجار؟","options":["بنيامين","يوسف","قيس","رفق"],"correct":2,"source":"سورة يوسف، الآية 19","explanation":"قالت الأخت: «قيس أبى أن يبيعهم» فكان هو من أقنع إخوته ببيع يوسف."},{"question":"ما هو الثواب الأكبر للصائم إذا صام صومًا مقصودًا؟","options":["مغفرة الذنوب","زيادة الرزق","تحصيل الأجر في الجنة","قضاء العدة"],"correct":0,"source":"صحيح البخاري، حديث 1902","explanation":"قال النبي ﷺ: «الصوم جنة»، فمغفرة الذنوب من أعظم ما يُعطى للصائم."},{"question":"أي آية من القرآن تؤكد الإيمان بالملائكة؟","options":["سورة الزخرف، الآية 71","سورة الإخلاص، الآية 1","سورة الفاتحة، الآية 2","سورة البقرة، الآية 255"],"correct":0,"source":"سورة الزخرف، الآية 71","explanation":"قال الله تعالى: {إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً}."},{"question":"في أي سنة هجرية هاجر النبي ﷺ من مكة إلى المدينة؟","options":["سنة 1 هـ","سنة 2 هـ","سنة 3 هـ","سنة 4 هـ"],"correct":0,"source":"السيرة النبوية، ابن كثير","explanation":"الهجرة حدثت في السنة الأولى للهجرة، أي 622 م، وتُعدّ بداية التقويم الهجري."},{"question":"كم عدد ركعات صلاة الفجر في السنة الواحدة (الفرض)؟","options":["2","3","4","5"],"correct":0,"source":"صحيح مسلم، كتاب الصلاة، حديث 425","explanation":"صلاة الفجر تتكوّن من ركعتين فرضًا."}]'::jsonb, 'openai/gpt-oss-120b'
where not exists (
  select 1 from public.worship_quiz_bank
  where questions = '[{"question":"ما هو الهدف الأساسي من خلق الإنسان حسب القرآن الكريم؟","options":["لعبادة الله","لتملك الأرض","للتمتع بالحياة الدنيوية","لإثبات التفوق البشري"],"correct":0,"source":"سورة الذاريات، الآية 56","explanation":"قال الله تعالى: {وما خلقت الجن والإنس إلا ليعبدون} وهو الهدف من الخلق."},{"question":"ما هو شرط صحة العمل في الإسلام بحسب الحديث النبوي؟","options":["النية الصادقة","الوقت المناسب","المكان المناسب","الملابس النظيفة"],"correct":0,"source":"صحيح البخاري، حديث 1","explanation":"قال النبي ﷺ: «إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى»."},{"question":"أي من الأسماء التالية من أسماء الله الحسنى يدل على وحدانية الله؟","options":["الرحمن","القدوس","الغفور","الواسع"],"correct":1,"source":"سورة الحجر، الآية 23","explanation":"قال الله تعالى: {هو الله الواحد الصمد} ومن أسمائه «القدوس» تدل على تنزيه الله عن كل نقص."},{"question":"في أي سورة نزل أولى آيات الوحي على النبي محمد ﷺ؟","options":["سورة الفاتحة","سورة البقرة","سورة العلق","سورة الإخلاص"],"correct":2,"source":"سورة العلق، الآيات 1-5","explanation":"نزلت أولى كلمات الوحي في: «اقرأ باسم ربك الذي خلق…»"},{"question":"أي من الأركان التالية ليست من أركان الوضوء بحسب السنة النبوية؟","options":["غسل الوجه","غسل اليدين","غسل القدمين","غسل الأذنين"],"correct":3,"source":"صحيح مسلم، كتاب الوضوء، حديث 258","explanation":"الوضوء يتضمن غسل الوجه، اليدين، مسح الرأس، وغسل القدمين، ولا يشمل غسل الأذنين."},{"question":"من هو الأخ الذي باع يوسف عليه السلام إلى التجار؟","options":["بنيامين","يوسف","قيس","رفق"],"correct":2,"source":"سورة يوسف، الآية 19","explanation":"قالت الأخت: «قيس أبى أن يبيعهم» فكان هو من أقنع إخوته ببيع يوسف."},{"question":"ما هو الثواب الأكبر للصائم إذا صام صومًا مقصودًا؟","options":["مغفرة الذنوب","زيادة الرزق","تحصيل الأجر في الجنة","قضاء العدة"],"correct":0,"source":"صحيح البخاري، حديث 1902","explanation":"قال النبي ﷺ: «الصوم جنة»، فمغفرة الذنوب من أعظم ما يُعطى للصائم."},{"question":"أي آية من القرآن تؤكد الإيمان بالملائكة؟","options":["سورة الزخرف، الآية 71","سورة الإخلاص، الآية 1","سورة الفاتحة، الآية 2","سورة البقرة، الآية 255"],"correct":0,"source":"سورة الزخرف، الآية 71","explanation":"قال الله تعالى: {إِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً}."},{"question":"في أي سنة هجرية هاجر النبي ﷺ من مكة إلى المدينة؟","options":["سنة 1 هـ","سنة 2 هـ","سنة 3 هـ","سنة 4 هـ"],"correct":0,"source":"السيرة النبوية، ابن كثير","explanation":"الهجرة حدثت في السنة الأولى للهجرة، أي 622 م، وتُعدّ بداية التقويم الهجري."},{"question":"كم عدد ركعات صلاة الفجر في السنة الواحدة (الفرض)؟","options":["2","3","4","5"],"correct":0,"source":"صحيح مسلم، كتاب الصلاة، حديث 425","explanation":"صلاة الفجر تتكوّن من ركعتين فرضًا."}]'::jsonb
);

-- مجموعة: ١٠ أسئلة (نفس عقد StoredQuestion)
insert into public.worship_quiz_bank (questions, model)
select '[{"question":"في أي سورة وردت الآية \"قُلْ هُوَ اللَّهُ أَحَدٌ\"؟","options":["سورة الإخلاص","سورة الفاتحة","سورة البقرة","سورة الناس"],"correct":0,"source":"سورة الإخلاص، الآية 1","explanation":"هذه الآية هي أول آية من سورة الإخلاص التي تتحدث عن توحيد الله."},{"question":"أي حديث صحيح يذكر أن \"إنما الأعمال بالنيات\"؟","options":["صحيح البخاري، حديث 1","صحيح مسلم، حديث 1907","سنن أبو داود، حديث 2020","جامع الترمذي، حديث 251"],"correct":0,"source":"صحيح البخاري، كتاب النية، باب ما جاء في النية، حديث رقم 1","explanation":"هذا الحديث يوضح أن الأجر يعتمد على نية الفاعل وهو من أصح أحاديث البخاري."},{"question":"أي مما يلي يُعد من أركان الإيمان الستة؟","options":["الإيمان بالملائكة","الإيمان بالقدر","الإيمان بالآخرة","الإيمان بالقرآن"],"correct":0,"source":"العقيدة الإسلامية المتفق عليها","explanation":"الإيمان بالملائكة هو أحد أركان الإيمان الستة في العقيدة الإسلامية."},{"question":"في أي سنة هجرية هاجر النبي ﷺ من مكة إلى المدينة؟","options":["السنة الأولى (1 هـ)","السنة الثانية (2 هـ)","السنة الثالثة (3 هـ)","السنة الرابعة (4 هـ)"],"correct":0,"source":"السيرة النبوية، السنة الأولى للهجرة، 1 هـ","explanation":"الهجرة وقعت في السنة الأولى للهجرة، أي بعد ولادة الإسلام عام 622 م."},{"question":"أي من الأركان التالية يُعد ركنًا من أركان الصلاة؟","options":["قراءة الفاتحة","القيام بالسجود","ارتداء الحجاب","إيتاء الزكاة"],"correct":1,"source":"صحيح مسلم، كتاب الصلاة، حديث رقم 449","explanation":"السجود هو أحد أركان الصلاة التي لا تصح بدونها."},{"question":"أي سورة تُعرف بـ \"أم الكتاب\"؟","options":["سورة البقرة","سورة آل عمران","سورة الأنعام","سورة الملك"],"correct":0,"source":"القرآن الكريم، سورة البقرة","explanation":"سورة البقرة تُسمى أم الكتاب لأنها أطول سورة وتحتوي على أحكام كثيرة."},{"question":"أي حديث صحيح يذكر أن \"خيركم من تعلم القرآن وعلمه\"؟","options":["صحيح البخاري، حديث 5027","صحيح مسلم، حديث 2739","سنن ابن ماجه، حديث 2361","مسند أحمد، حديث 3456"],"correct":0,"source":"صحيح البخاري، كتاب القراءة، حديث رقم 5027","explanation":"الحديث يحث على تعلم القرآن وتعليمه للآخرين وهو من أحاديث البخاري الصحيحة."},{"question":"ما المصطلح الذي يدل على الإيمان بعدم شريك لله؟","options":["التوحيد","الرسالة","الشريعة","الإجتهاد"],"correct":0,"source":"العقيدة الإسلامية المتفق عليها","explanation":"التوحيد هو الإيمان بأن لا شريك لله في العبادة أو الألوهية."},{"question":"من هي أول من أسلم من النساء؟","options":["خديجة رضي الله عنها","عائشة رضي الله عنها","فاطمة رضي الله عنها","زينب رضي الله عنها"],"correct":0,"source":"سيرة النبي، صحيح البخاري، حديث 6","explanation":"خديجة رضي الله عنها كانت أول من أسلم من النساء، وهي زوجة النبي ﷺ."},{"question":"في شهر رمضان، ما هو الفطر التقليدي المتبع عند انتهاء الصوم؟","options":["تمر وماء","حليب","لحم","عصير فواكه"],"correct":0,"source":"صحيح مسلم، باب صوم رمضان، حديث رقم 1151","explanation":"النبي ﷺ كان يفطر على تمر وماء، وهذا هو الفطر المستحب."}]'::jsonb, 'openai/gpt-oss-120b'
