-- مجموعة: ١٠ أسئلة (نفس عقد StoredQuestion)
insert into public.worship_quiz_bank (questions, model)
select '[{"question":"ما هو اسم السورة التي نزلت فيها آية الكرسي؟","options":["سورة البقرة","سورة آل عمران","سورة النساء","سورة المائدة"],"correct":0,"source":"سورة البقرة، الآية 255","explanation":"آية الكرسي وردت في سورة البقرة في الآية رقم 255."},{"question":"كم عدد الركعات في صلاة الفجر؟","options":["ركعتان","ثلاث ركعات","أربع ركعات","خمس ركعات"],"correct":0,"source":"صحيح البخاري، باب صلاة الفجر، حديث رقم 724","explanation":"صلاة الفجر تتكون من ركعتين فرضيتين."},{"question":"أيٌّ من الأركان التالية يُعَدُّ من أركان الإيمان؟","options":["الصوم","الصلاة","الإيمان بالملائكة","الحج"],"correct":2,"source":"سورة البقرة، الآية 285","explanation":"الإيمان بالملائكة من أركان الإيمان كما ذكر في قوله تعالى: \"آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ\"."},{"question":"في أي عام هاجر النبي ﷺ من مكة إلى المدينة؟","options":["610 م","615 م","622 م","630 م"],"correct":2,"source":"السيرة النبوية، سنة الهجرة 1 هـ (622 م)","explanation":"الهجرة حدثت في السنة الأولى للهجرة، أي 622 م."},{"question":"ما هو الركن الأول من أركان الإسلام؟","options":["الصلاة","الشهادة","الزكاة","الصوم"],"correct":1,"source":"صحيح مسلم، باب الإيمان، حديث رقم 1","explanation":"الشهادة (الشهادتان) هي الركن الأول من أركان الإسلام."},{"question":"أيّ من الآيات التالية تُدْعَى آية السجدة؟","options":["الآية 30 من سورة السجدة","الآية 30 من سورة مريم","الآية 30 من سورة النمل","الآية 30 من سورة الروم"],"correct":0,"source":"سورة السجدة، الآية 30","explanation":"الآية 30 من سورة السجدة هي ما يُعرف بآية السجدة."},{"question":"ما هو الدعاء المستحب بعد التشهد الأخير في الصلاة؟","options":["اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم","اللهم إني أعوذ بك من شر ما عملت","اللهم إني أسألك الجنة","اللهم لا إله إلا أنت"],"correct":0,"source":"صحيح البخاري، باب دعاء التشهد الأخير، حديث رقم 1135","explanation":"الأصح أن يُختتم التشهد الأخير بالدعاء: \"اللهم صل على محمد وعلى آل محمد...\""},{"question":"ما هو اسم الإله في الإسلام؟","options":["الله","يهوه","إله","أله"],"correct":0,"source":"سورة الفاتحة، الآية 2","explanation":"الإله في الإسلام هو \"الله\" كما جاء في الفاتحة: \"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\"."},{"question":"من هو الصحابي الذي لُقّب بـ«سيد القوم»؟","options":["أبو بكر الصديق","عمر بن الخطاب","علي بن أبي طالب","عبد الله بن مسعود"],"correct":0,"source":"صحيح البخاري، باب سيرة أبي بكر الصديق، حديث رقم 3865","explanation":"أبو بكر الصديق لُقّب بـ«سيد القوم» في عدة أحاديث صحيحة."},{"question":"ما هو الركن الأخير من أركان الصلاة؟","options":["القراءة","الركوع","السجود","التشهد الأخير"],"correct":3,"source":"صحيح مسلم، باب أركان الصلاة، حديث رقم 425","explanation":"التشهد الأخير (التشهد والتسليم) هو الركن الأخير في إتمام الصلاة."}]'::jsonb, 'openai/gpt-oss-120b'
where not exists (
  select 1 from public.worship_quiz_bank
  where questions = '[{"question":"ما هو اسم السورة التي نزلت فيها آية الكرسي؟","options":["سورة البقرة","سورة آل عمران","سورة النساء","سورة المائدة"],"correct":0,"source":"سورة البقرة، الآية 255","explanation":"آية الكرسي وردت في سورة البقرة في الآية رقم 255."},{"question":"كم عدد الركعات في صلاة الفجر؟","options":["ركعتان","ثلاث ركعات","أربع ركعات","خمس ركعات"],"correct":0,"source":"صحيح البخاري، باب صلاة الفجر، حديث رقم 724","explanation":"صلاة الفجر تتكون من ركعتين فرضيتين."},{"question":"أيٌّ من الأركان التالية يُعَدُّ من أركان الإيمان؟","options":["الصوم","الصلاة","الإيمان بالملائكة","الحج"],"correct":2,"source":"سورة البقرة، الآية 285","explanation":"الإيمان بالملائكة من أركان الإيمان كما ذكر في قوله تعالى: \"آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ\"."},{"question":"في أي عام هاجر النبي ﷺ من مكة إلى المدينة؟","options":["610 م","615 م","622 م","630 م"],"correct":2,"source":"السيرة النبوية، سنة الهجرة 1 هـ (622 م)","explanation":"الهجرة حدثت في السنة الأولى للهجرة، أي 622 م."},{"question":"ما هو الركن الأول من أركان الإسلام؟","options":["الصلاة","الشهادة","الزكاة","الصوم"],"correct":1,"source":"صحيح مسلم، باب الإيمان، حديث رقم 1","explanation":"الشهادة (الشهادتان) هي الركن الأول من أركان الإسلام."},{"question":"أيّ من الآيات التالية تُدْعَى آية السجدة؟","options":["الآية 30 من سورة السجدة","الآية 30 من سورة مريم","الآية 30 من سورة النمل","الآية 30 من سورة الروم"],"correct":0,"source":"سورة السجدة، الآية 30","explanation":"الآية 30 من سورة السجدة هي ما يُعرف بآية السجدة."},{"question":"ما هو الدعاء المستحب بعد التشهد الأخير في الصلاة؟","options":["اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم","اللهم إني أعوذ بك من شر ما عملت","اللهم إني أسألك الجنة","اللهم لا إله إلا أنت"],"correct":0,"source":"صحيح البخاري، باب دعاء التشهد الأخير، حديث رقم 1135","explanation":"الأصح أن يُختتم التشهد الأخير بالدعاء: \"اللهم صل على محمد وعلى آل محمد...\""},{"question":"ما هو اسم الإله في الإسلام؟","options":["الله","يهوه","إله","أله"],"correct":0,"source":"سورة الفاتحة، الآية 2","explanation":"الإله في الإسلام هو \"الله\" كما جاء في الفاتحة: \"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\"."},{"question":"من هو الصحابي الذي لُقّب بـ«سيد القوم»؟","options":["أبو بكر الصديق","عمر بن الخطاب","علي بن أبي طالب","عبد الله بن مسعود"],"correct":0,"source":"صحيح البخاري، باب سيرة أبي بكر الصديق، حديث رقم 3865","explanation":"أبو بكر الصديق لُقّب بـ«سيد القوم» في عدة أحاديث صحيحة."},{"question":"ما هو الركن الأخير من أركان الصلاة؟","options":["القراءة","الركوع","السجود","التشهد الأخير"],"correct":3,"source":"صحيح مسلم، باب أركان الصلاة، حديث رقم 425","explanation":"التشهد الأخير (التشهد والتسليم) هو الركن الأخير في إتمام الصلاة."}]'::jsonb
